class RequestCounter {
    private int count = 0;  // shared mutable state

    public void incrementCount() {
        count++;  // NOT atomic - three operations: read, add, write
    }

    public int getCount() {
        return count;
    }
}

// In production:
var counter = new RequestCounter();
var executor = Executors.newFixedThreadPool(10);

for (int i = 0; i < 1000; i++) {
    executor.submit(() -> counter.incrementCount());  // 1000 concurrent calls
}
executor.shutdown();
executor.awaitTermination(1, TimeUnit.MINUTES);

System.out.println(counter.getCount());  // Expected 1000, actual < 1000 (lost updates)

class BankAccount {
    private int balance;

    public synchronized void transfer(BankAccount target, int amount) {
        this.balance -= amount;  // holding lock on 'this'
        synchronized (target) {  // waiting for lock on 'target' - DEADLOCK RISK
            target.balance += amount;
        }
    }
}

// Deadlock scenario:
var accountA = new BankAccount();
var accountB = new BankAccount();

// Thread 1: A -> B
new Thread(() -> accountA.transfer(accountB, 100)).start();

// Thread 2: B -> A (opposite lock order)
new Thread(() -> accountB.transfer(accountA, 50)).start();

// If Thread 1 locks A and Thread 2 locks B simultaneously,
// both will wait forever for the other's lock - deadlock!

class SharedResource {
    private final Object lock = new Object();

    public void performWork(String threadName) {
        while (true) {
            synchronized (lock) {  // default locks are unfair
                System.out.println(threadName + " got the lock");
                // simulate work
                try { Thread.sleep(10); } catch (InterruptedException e) {}
            }
            // Brief unlock period - but same threads tend to reacquire
        }
    }
}

var resource = new SharedResource();
var lowPriority = new Thread(() -> resource.performWork("Low"));
var highPriority = new Thread(() -> resource.performWork("High"));

lowPriority.setPriority(Thread.MIN_PRIORITY);  // priority 1
highPriority.setPriority(Thread.MAX_PRIORITY); // priority 10

lowPriority.start();
highPriority.start();
// Result: "Low" thread may never get the lock on a busy system

class HitCounter {
    private int hits = 0;  // shared mutable state

    public void recordHit() {
        hits++;  // NOT atomic! Compiles to: load, add, store
    }

    public int getHits() {
        return hits;
    }
}

// Interleaving scenario:
// Thread A                  Thread B
// read hits (0)             
//                           read hits (0)
// add 1 (result=1)          
//                           add 1 (result=1)
// write hits=1              
//                           write hits=1
// Result: both increments happened, but hits=1 instead of 2

// Fix with AtomicInteger:
class SafeHitCounter {
    private final AtomicInteger hits = new AtomicInteger(0);

    public void recordHit() {
        hits.incrementAndGet();  // atomic operation
    }
}

class TaskRunner {
    private boolean taskCompleted = false;  // NOT volatile - visibility problem

    public void completeTask() {
        // Called by Thread A
        System.out.println("Task completed");
        taskCompleted = true;  // write may stay in Thread A's cache
    }

    public void waitForTask() {
        // Called by Thread B
        while (!taskCompleted) {  // may read stale value forever
            // Thread B might never see the update from Thread A
        }
        System.out.println("Proceeding after task completion");
    }
}

// Fix: add volatile to enforce visibility
class SafeTaskRunner {
    private volatile boolean taskCompleted = false;  // volatile ensures visibility

    public void completeTask() {
        taskCompleted = true;  // write immediately visible to all threads
    }

    public void waitForTask() {
        while (!taskCompleted) {}
    }
}
